  cursor: pointer;
  font-size: 14px;
  font-weight: 600;
  transition: background 0.15s;
}

#btn-save {
  background: var(--accent);
  color: #fff;
  flex: 1;
}

#btn-save:hover {
  background: var(--accent-hover);
}

#btn-delete {
  background: var(--danger);
  color: #fff;
}

#btn-delete:hover {
  background: var(--danger-hover);
}

#btn-cancel {
  background: #f1f5f9;
  color: var(--text-primary);
}

#btn-cancel:hover {
  background: #e2e8f0;
}

button.hidden {
  display: none !important;
}

/* ── Scrollbar ────────────────────────────────────────────────────────────── */
#days-wrapper::-webkit-scrollbar {
