/* ── Time Grid Lines ──────────────────────────────────────────────────────── */
.day-body {
  position: relative;
  height: var(--axis-height);
  width: 100%;
}

.hour-line {
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--hour-line-color);
  pointer-events: none;
}

.half-line {
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--half-line-color);
  pointer-events: none;
}

/* Drag-selection highlight */
.drag-selection {
  position: absolute;
  left: 2px;
  right: 2px;
  background: rgba(59, 130, 246, 0.15);
  border: 1px dashed var(--accent);
  border-radius: var(--event-radius);
  pointer-events: none;
  z-index: 2;
}

/* ── Event Blocks ─────────────────────────────────────────────────────────── */
.event-block {
  position: absolute;
  border-radius: var(--event-radius);
  background: var(--event-default-bg);
  border-left: 3px solid var(--event-default-border);
  color: #fff;
  padding: 2px 5px;
  overflow: hidden;
  cursor: pointer;
  z-index: 3;
  transition: filter 0.1s;
  /* Prevent text selection during drag */
  user-select: none;
}

.event-block:hover {
  filter: brightness(1.1);
  z-index: 4;
}

.event-block .ev-title {
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.3;
}

.event-block .ev-time {
  font-size: 10px;
  opacity: 0.9;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.3;
}

/* ── Modal ────────────────────────────────────────────────────────────────── */
#modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
}

#modal-overlay.hidden {
  display: none;
}

#modal-box {
  background: #fff;
  border-radius: 10px;
  padding: 24px;
  width: 360px;
  max-width: 95vw;
  box-shadow: 0 20px 60px rgba(0,0,0,0.2);
}

#modal-title {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 16px;
  color: var(--text-primary);
}

#event-form label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
  margin-bottom: 4px;
  margin-top: 12px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

#event-form label:first-of-type {
  margin-top: 0;
}

#event-form input {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  font-size: 14px;
  color: var(--text-primary);
  outline: none;
  transition: border-color 0.15s;
}

#event-form input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(59,130,246,0.15);
}

.form-error {
  margin-top: 10px;
  padding: 8px 10px;
  background: #fef2f2;
  border: 1px solid #fecaca;
  border-radius: 6px;
  color: var(--danger);
  font-size: 13px;
}

.form-error.hidden {
  display: none;
}

.form-actions {
  display: flex;
  gap: 8px;
  margin-top: 20px;
}

.form-actions button {
  padding: 8px 18px;
  border-radius: 6px;
  border: none;
  cursor: pointer;
  font-size: 14px;
  font-weight: 600;
  transition: background 0.15s;
}

#btn-save {
  background: var(--accent);
  color: #fff;
  flex: 1;
}

#btn-save:hover {
  background: var(--accent-hover);
}

#btn-delete {
  background: var(--danger);
  color: #fff;
}

#btn-delete:hover {
  background: var(--danger-hover);
}

#btn-cancel {
  background: #f1f5f9;
  color: var(--text-primary);
}

#btn-cancel:hover {
  background: #e2e8f0;
}

button.hidden {
  display: none !important;
}

/* ── Scrollbar ────────────────────────────────────────────────────────────── */
#days-wrapper::-webkit-scrollbar {
  width: 8px;
}
#days-wrapper::-webkit-scrollbar-track {
  background: #f1f5f9;
}
#days-wrapper::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 4px;
}

/* ── Responsive ───────────────────────────────────────────────────────────── */
@media (max-width: 640px) {
  :root {
    --gutter-width: 36px;
    --hour-height: 48px;
  }
  .day-header .day-date {
    font-size: 15px;
  }
  .day-header .day-name {
    font-size: 9px;
  }
}
"}

