}", "new_str": "function attachDragCreate(body, day) {
  let dragStart = null;
  let selectionEl = null;

  function yToMinutes(y) {
    const raw = (y / AXIS_HEIGHT) * TOTAL_MINUTES;
    return Math.max(0, Math.min(TOTAL_MINUTES, snapMinutes(raw, SNAP)));
  }

  function minutesToY(min) {
    return (min / TOTAL_MINUTES) * AXIS_HEIGHT;
  }

  /**
   * Convert a mouse clientY to a y-position within the body element,
   * accounting for the scroll offset of the days-wrapper.
   */
  function clientYToBodyY(clientY) {
    const wrapper = daysWrapper;
    const rect = body.getBoundingClientRect();
    // rect.top already accounts for scroll (it's the visible position),
    // but body is absolutely positioned inside the scrollable wrapper.
    // We need position relative to the body's top edge.
    return clientY - rect.top;
  }

  body.addEventListener('mousedown', e => {
    // Only left-click on the body itself or grid lines (not on event blocks)
    if (e.button !== 0) return;
    if (
      e.target !== body &&
      !e.target.classList.contains('hour-line') &&
      !e.target.classList.contains('half-line')
    ) return;

    e.preventDefault();
    const y = clientYToBodyY(e.clientY);
    dragStart = yToMinutes(y);

    selectionEl = document.createElement('div');
    selectionEl.className = 'drag-selection';
    const snapY = minutesToY(dragStart);
    selectionEl.style.top    = `${snapY}px`;
    selectionEl.style.height = `${HOUR_HEIGHT}px`; // default 1 hour preview
    body.appendChild(selectionEl);
  });

  document.addEventListener('mousemove', onMouseMove);
  document.addEventListener('mouseup', onMouseUp);

  function onMouseMove(e) {
    if (dragStart === null || !selectionEl) return;
    const y = clientYToBodyY(e.clientY);
    const currentMin = yToMinutes(y);

    const startMin   = Math.min(dragStart, currentMin);
    const endMin     = Math.max(dragStart, currentMin);
    const clampedEnd = endMin === startMin ? startMin + SNAP : endMin;

    selectionEl.style.top    = `${minutesToY(startMin)}px`;
    selectionEl.style.height = `${minutesToY(clampedEnd) - minutesToY(startMin)}px`;
  }

  function onMouseUp(e) {
    if (dragStart === null || !selectionEl) return;

    const y      = clientYToBodyY(e.clientY);
    const endMin = yToMinutes(y);

    let startMin = Math.min(dragStart, endMin);
    let finalEnd = Math.max(dragStart, endMin);
    if (finalEnd === startMin) finalEnd = startMin + SNAP;

    // Clamp to valid range
    startMin = Math.max(0, Math.min(TOTAL_MINUTES - SNAP, startMin));
    finalEnd = Math.max(startMin + SNAP, Math.min(TOTAL_MINUTES, finalEnd));

    selectionEl.remove();
    selectionEl = null;
    dragStart = null;

    // Build Date objects for the selected time range on this day
    const startDate = new Date(day);
    startDate.setHours(Math.floor(startMin / 60), startMin % 60, 0, 0);
    const endDate = new Date(day);
    endDate.setHours(Math.floor(finalEnd / 60), finalEnd % 60, 0, 0);

    openCreateModal(startDate, endDate);
  }
}"}

{"path": "client/src/layout.js", "content": "/**
 * Cluster-based overlap layout engine.
 *
 * Given a list of events for a single day, computes for each event:
 *   - colIndex:    which column within its cluster (0-based)
 *   - colCount:    the number of columns this event must share
 *                  (= the maximum number of simultaneously active columns
 *                   at any point during this event's duration)
 *
 * The caller maps these to pixel geometry:
 *   left  = (colIndex / colCount) * dayColumnWidth
 *   width = dayColumnWidth / colCount
 *
 * ── Algorithm ────────────────────────────────────────────────────────────────
 *
 * Phase 1 – Cluster detection (transitive overlap grouping)
 *   Sort events by start time. Sweep through; maintain the running maximum
 *   end time of the current cluster. When an event starts at or after that
 *   maximum, it belongs to a new cluster.
 *
 * Phase 2 – Column assignment (greedy, within each cluster)
 *   Maintain colEnds[c] = end time of the last event placed in column c.
 *   For each event (sorted by start, then longer-first), find the first
 *   column c where colEnds[c] <= event.start; assign it there and update
 *   colEnds[c] = event.end. If no free column exists, open a new one.
 *
 * Phase 3 – Per-event colCount (contention width)
 *   For each event, colCount = the number of columns that are "active"
 *   (i.e. have an event overlapping this event's time range) at the moment
 *   of maximum contention during this event's duration.
 *   Concretely: for event E, count how many other events in the same cluster
 *   overlap E (start_other < end_E AND end_other > start_E), then add 1 for
 *   E itself. That is the colCount for E.
 *
 *   This ensures:
 *   - An event that overlaps nothing gets colCount = 1 (full width).
 *   - In a chain A–B–C where A overlaps B and B overlaps C but A does not
 *     overlap C: A gets colCount = 2, B gets colCount = 2, C gets colCount = 2
 *     (B is the bottleneck). Each event is still fully visible.
 *   - Three identical-time events each get colCount = 3.
 */

/**
 * @typedef {{ id: number, start_at: string, end_at: string, title: string }} CalEvent
 * @typedef {{ event: CalEvent, colIndex: number, colCount: number }} LayoutItem
 */

/**
 * @param {CalEvent[]} events  All events for one day (any order).
 * @returns {LayoutItem[]}
 */
export function computeDayLayout(events) {
  if (events.length === 0) return [];

  // Convert to working objects with numeric timestamps
  const items = events.map(ev => ({
    event:    ev,
    start:    new Date(ev.start_at).getTime(),
    end:      new Date(ev.end_at).getTime(),
    colIndex: 0,
    colCount: 1,
  }));

  // Sort by start time, then by end time descending (longer events first)
  items.sort((a, b) => a.start - b.start || b.end - a.end);

  // ── Phase 1: Build clusters ───────────────────────────────────────────────
  const clusters = [];
  let currentCluster = [];
  let clusterMaxEnd  = -Infinity;

  for (const item of items) {
    if (currentCluster.length > 0 && item.start >= clusterMaxEnd) {
      clusters.push(currentCluster);
      currentCluster = [];
      clusterMaxEnd  = -Infinity;
    }
    currentCluster.push(item);
    if (item.end > clusterMaxEnd) clusterMaxEnd = item.end;
  }
  if (currentCluster.length > 0) clusters.push(currentCluster);

  // ── Phase 2 & 3: Column assignment + per-event colCount ──────────────────
  for (const cluster of clusters) {
    // ── 2a. Assign column indices greedily ──────────────────────────────
    const colEnds = []; // colEnds[c] = end time of last event in column c

    for (const item of cluster) {
      let placed = false;
      for (let c = 0; c < colEnds.length; c++) {
        if (colEnds[c] <= item.start) {
          item.colIndex = c;
          colEnds[c]    = item.end;
          placed = true;
          break;
        }
      }
      if (!placed) {
        item.colIndex = colEnds.length;
        colEnds.push(item.end);
      }
    }

    // ── 2b. Compute per-event colCount ──────────────────────────────────
    // For each event E, colCount(E) = 1 + number of other events in the
    // cluster that overlap E.
    // Two events overlap iff start_a < end_b AND start_b < end_a.
    for (const item of cluster) {
      let overlapping = 1; // count E itself
      for (const other of cluster) {
        if (other === item) continue;
        if (other.start < item.end && other.end > item.start) {
          overlapping++;
        }
      }
      item.colCount = overlapping;
    }
  }

  return items.map(item => ({
    event:    item.event,
    colIndex: item.colIndex,
    colCount: item.colCount,
  }));
}
"}

{"path": "client/src/layout.js", "content": "/**
 * Cluster-based overlap layout engine.
 *
 * Given a list of events for a single day, computes for each event:
 *   - colIndex:    which column within its cluster (0-based)
 *   - colCount:    total columns opened in this event's cluster
 *
 * The caller maps these to pixel geometry:
 *   left  = (colIndex / colCount) * dayColumnWidth
 *   width = dayColumnWidth / colCount
 *
 * ── Algorithm ────────────────────────────────────────────────────────────────
 *
 * Phase 1 – Cluster detection (transitive overlap grouping)
 *   Sort events by start time. Sweep through; maintain the running maximum
 *   end time of the current cluster. When an event starts at or after that
 *   maximum, it belongs to a new cluster. This correctly groups transitively
 *   overlapping events: if A overlaps B and B overlaps C (but A doesn't
 *   overlap C), all three are in the same cluster.
 *
 * Phase 2 – Column assignment (greedy, within each cluster)
 *   Maintain colEnds[c] = end time of the last event placed in column c.
 *   For each event (sorted by start, then longer-first), find the first
 *   column c where colEnds[c] <= event.start; assign it there and update
 *   colEnds[c] = event.end. If no free column exists, open a new one.
 *   colCount for every event in the cluster = total columns opened.
 *
 * This guarantees:
 *   - No two events in the same cluster share a column at the same time
 *     → no visual overlap.
 *   - Events in different clusters (non-overlapping) each get their own
 *     cluster with colCount = 1 → full day-column width.
 *   - N identical-time events → N columns → each gets width 1/N.
 *   - Partially overlapping chains: all events in the chain share the same
 *     colCount (= max simultaneous overlap in the chain), ensuring consistent
 *     horizontal geometry with no visual overlap.
 */

/**
 * @typedef {{ id: number, start_at: string, end_at: string, title: string }} CalEvent
 * @typedef {{ event: CalEvent, colIndex: number, colCount: number }} LayoutItem
 */

/**
 * @param {CalEvent[]} events  All events for one day (any order).
 * @returns {LayoutItem[]}
 */
export function computeDayLayout(events) {
  if (events.length === 0) return [];

  // Convert to working objects with numeric timestamps
  const items = events.map(ev => ({
    event:    ev,
    start:    new Date(ev.start_at).getTime(),
    end:      new Date(ev.end_at).getTime(),
    colIndex: 0,
    colCount: 1,
  }));

  // Sort by start time, then by end time descending (longer events first)
  items.sort((a, b) => a.start - b.start || b.end - a.end);

  // ── Phase 1: Build clusters ───────────────────────────────────────────────
  // A cluster is a maximal set of transitively overlapping events.
  // The sweep correctly handles transitive overlap: if A overlaps B and B
  // overlaps C, the cluster's running max-end will still be >= C's start.
  const clusters = [];
  let currentCluster = [];
  let clusterMaxEnd  = -Infinity;

  for (const item of items) {
    if (currentCluster.length > 0 && item.start >= clusterMaxEnd) {
      // This event doesn't overlap anything in the current cluster
      clusters.push(currentCluster);
      currentCluster = [];
      clusterMaxEnd  = -Infinity;
    }
    currentCluster.push(item);
    if (item.end > clusterMaxEnd) clusterMaxEnd = item.end;
  }
  if (currentCluster.length > 0) clusters.push(currentCluster);

  // ── Phase 2: Assign columns within each cluster ───────────────────────────
  for (const cluster of clusters) {
    // colEnds[c] = end time of the last event placed in column c
    const colEnds = [];

    for (const item of cluster) {
      // Find the first column that is free at item.start
      let placed = false;
      for (let c = 0; c < colEnds.length; c++) {
        if (colEnds[c] <= item.start) {
          item.colIndex = c;
          colEnds[c]    = item.end;
          placed = true;
          break;
        }
      }
      if (!placed) {
        // All existing columns are busy; open a new one
        item.colIndex = colEnds.length;
        colEnds.push(item.end);
      }
    }

    // All events in this cluster share the same colCount
    const colCount = colEnds.length;
    for (const item of cluster) {
      item.colCount = colCount;
    }
  }

  return items.map(item => ({
    event:    item.event,
    colIndex: item.colIndex,
    colCount: item.colCount,
  }));
}
"}

