{"path": "client/src/layout.js", "content": "/**
 * Cluster-based overlap layout engine.
 *
 * Given a list of events for a single day, computes for each event:
 *   - colIndex:    which column within its cluster (0-based)
 *   - colCount:    total columns in its cluster
 *
 * The caller then maps these to pixel geometry:
 *   left  = (colIndex / colCount) * dayColumnWidth
 *   width = dayColumnWidth / colCount
 *
 * Algorithm:
 *   1. Sort events by start_at, then by end_at descending (longer first).
 *   2. Build overlap clusters: a cluster is a maximal set of events where
 *      every event overlaps at least one other event in the set (transitive).
 *      Two events overlap iff start_a < end_b AND start_b < end_a.
 *   3. Within each cluster, assign column indices greedily:
 *      - Maintain a list of "column end times" (initially empty).
 *      - For each event (in sorted order), find the first column whose
 *        current end time <= event.start_at; assign that column and update
 *        its end time. If none found, open a new column.
 *   4. colCount for every event in the cluster = number of columns opened.
 */

/**
 * @typedef {{ id: number, start_at: string, end_at: string, title: string }} CalEvent
 * @typedef {{ event: CalEvent, colIndex: number, colCount: number }} LayoutItem
 */

/**
 * @param {CalEvent[]} events  All events for one day (any order).
 * @returns {LayoutItem[]}
 */
export function computeDayLayout(events) {
  if (events.length === 0) return [];

  // Convert to working objects with numeric timestamps
  const items = events.map(ev => ({
    event: ev,
    start: new Date(ev.start_at).getTime(),
    end:   new Date(ev.end_at).getTime(),
    colIndex: 0,
    colCount: 1,
  }));

  // Sort by start time, then by end time descending (longer events first)
  items.sort((a, b) => a.start - b.start || b.end - a.end);

  // ── Step 1: Build clusters ────────────────────────────────────────────────
  // We use a sweep: maintain the maximum end time seen so far in the current
  // cluster. When a new event starts at or after that max end, it starts a
  // new cluster.
  const clusters = [];
  let currentCluster = [];
  let clusterMaxEnd = -Infinity;

  for (const item of items) {
    if (currentCluster.length > 0 && item.start >= clusterMaxEnd) {
      // No overlap with anything in the current cluster → flush
      clusters.push(currentCluster);
      currentCluster = [];
      clusterMaxEnd = -Infinity;
    }
    currentCluster.push(item);
    if (item.end > clusterMaxEnd) clusterMaxEnd = item.end;
  }
  if (currentCluster.length > 0) clusters.push(currentCluster);

  // ── Step 2: Assign columns within each cluster ────────────────────────────
  for (const cluster of clusters) {
    // colEnds[i] = the end time of the last event placed in column i
    const colEnds = [];

    for (const item of cluster) {
      // Find the first column that is free at item.start
      let placed = false;
      for (let c = 0; c < colEnds.length; c++) {
        if (colEnds[c] <= item.start) {
          item.colIndex = c;
          colEnds[c] = item.end;
          placed = true;
          break;
        }
      }
      if (!placed) {
        item.colIndex = colEnds.length;
        colEnds.push(item.end);
      }
    }

    const colCount = colEnds.length;
    for (const item of cluster) {
      item.colCount = colCount;
    }
  }

  // ── Return ────────────────────────────────────────────────────────────────
  return items.map(item => ({
    event:    item.event,
    colIndex: item.colIndex,
    colCount: item.colCount,
  }));
}
"}

{"path": "client/src/api.js", "content": "const BASE = 'http://localhost:3001';

async function request(method, path, body) {
  const opts = {
    method,
    headers: { 'Content-Type': 'application/json' },
  };
  if (body !== undefined) {
    opts.body = JSON.stringify(body);
  }
  const res = await fetch(`${BASE}${path}`, opts);
  const data = await res.json();
  if (!res.ok) {
    const msg = data.errors ? data.errors.join('; ') : (data.error || 'Request failed');
    const err = new Error(msg);
    err.status = res.status;
    err.data = data;
    throw err;
  }
  return data;
}

/**
 * Fetch events overlapping [start, end) (ISO strings).
 * @param {string} start
 * @param {string} end
 * @returns {Promise<Array>}
 */
export function fetchEvents(start, end) {
  return request('GET', `/api/events?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}`);
}

/**
 * Create a new event.
 * @param {{ title: string, start_at: string, end_at: string }} ev
 */
export function createEvent(ev) {
  return request('POST', '/api/events', ev);
}

/**
 * Update an existing event.
 * @param {number} id
 * @param {{ title: string, start_at: string, end_at: string }} ev
 */
export function updateEvent(id, ev) {
  return request('PUT', `/api/events/${id}`, ev);
}

/**
 * Delete an event.
 * @param {number} id
 */
export function deleteEvent(id) {
  return request('DELETE', `/api/events/${id}`);
}
"}

{"path": "client/src/dates.js", "content": "/**
 * Date utilities for the week calendar.
 * All operations work in local time.
 */

/**
 * Return the Monday of the week containing `date`.
 * @param {Date} date
 * @returns {Date}
 */
export function getWeekStart(date) {
  const d = new Date(date);
  // getDay(): 0=Sun, 1=Mon, ..., 6=Sat
  const day = d.getDay();
  // Offset to Monday: if Sunday (0) → -6, else → -(day-1)
  const offset = day === 0 ? -6 : 1 - day;
  d.setDate(d.getDate() + offset);
  d.setHours(0, 0, 0, 0);
  return d;
}

/**
 * Return an array of 7 Date objects (Mon–Sun) for the week starting at `weekStart`.
 * @param {Date} weekStart  Must be a Monday at 00:00:00.
 * @returns {Date[]}
 */
export function getWeekDays(weekStart) {
  return Array.from({ length: 7 }, (_, i) => {
    const d = new Date(weekStart);
    d.setDate(d.getDate() + i);
    return d;
  });
}

/**
 * Add `n` weeks to a date, returning a new Date.
 * @param {Date} date
 * @param {number} n
 * @returns {Date}
 */
export function addWeeks(date, n) {
  const d = new Date(date);
  d.setDate(d.getDate() + n * 7);
  return d;
}

/**
 * Format a Date as "YYYY-MM-DDTHH:MM:SS" (local time, no timezone suffix).
 * @param {Date} date
 * @returns {string}
 */
export function toLocalIso(date) {
  const pad = n => String(n).padStart(2, '0');
  return (
    `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}` +
    `T${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`
  );
}

/**
 * Format a Date as "YYYY-MM-DDTHH:MM" for datetime-local inputs.
 * @param {Date} date
 * @returns {string}
 */
export function toInputDatetime(date) {
  const pad = n => String(n).padStart(2, '0');
  return (
    `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}` +
    `T${pad(date.getHours())}:${pad(date.getMinutes())}`
  );
}

/**
 * Format a Date as a short time string "HH:MM".
 * @param {Date} date
 * @returns {string}
 */
export function formatTime(date) {
  const pad = n => String(n).padStart(2, '0');
  return `${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

/**
 * Format a Date as "Mon 12" (day name + date number).
 * @param {Date} date
 * @returns {{ dayName: string, dayNum: number }}
 */
export function formatDayHeader(date) {
  const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  return {
    dayName: dayNames[date.getDay()],
    dayNum:  date.getDate(),
  };
}

/**
 * Format a week range label: "Jun 2 – Jun 8, 2025"
 * @param {Date} weekStart
 * @returns {string}
 */
export function formatWeekLabel(weekStart) {
  const weekEnd = new Date(weekStart);
  weekEnd.setDate(weekEnd.getDate() + 6);

  const monthNames = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const sm = monthNames[weekStart.getMonth()];
  const em = monthNames[weekEnd.getMonth()];
  const sy = weekStart.getFullYear();
  const ey = weekEnd.getFullYear();

  if (sy === ey) {
    if (sm === em) {
      return `${sm} ${weekStart.getDate()} – ${weekEnd.getDate()}, ${sy}`;
    }
    return `${sm} ${weekStart.getDate()} – ${em} ${weekEnd.getDate()}, ${sy}`;
  }
  return `${sm} ${weekStart.getDate()}, ${sy} – ${em} ${weekEnd.getDate()}, ${ey}`;
}

/**
 * Return true if two Date objects represent the same calendar day (local time).
 * @param {Date} a
 * @param {Date} b
 * @returns {boolean}
 */
export function isSameDay(a, b) {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth()    === b.getMonth()    &&
    a.getDate()     === b.getDate()
  );
}

/**
 * Return the number of minutes since midnight for a Date.
 * @param {Date} date
 * @returns {number}
 */
export function minutesFromMidnight(date) {
  return date.getHours() * 60 + date.getMinutes();
}

/**
 * Snap minutes to the nearest `snap` interval.
 * @param {number} minutes
 * @param {number} snap  e.g. 15
 * @returns {number}
 */
export function snapMinutes(minutes, snap = 15) {
  return Math.round(minutes / snap) * snap;
}
"}

{"path": "client/src/main.js", "content": "import './style.css';
import { computeDayLayout } from './layout.js';
import { fetchEvents, createEvent, updateEvent, deleteEvent } from './api.js';
import {
  getWeekStart,
  getWeekDays,
  addWeeks,
  toLocalIso,
  toInputDatetime,
  formatTime,
  formatDayHeader,
  formatWeekLabel,
  isSameDay,
  minutesFromMidnight,
  snapMinutes,
} from './dates.js';

// ── Constants ─────────────────────────────────────────────────────────────────
const HOUR_HEIGHT    = 60;   // px per hour  (must match CSS --hour-height)
const AXIS_HEIGHT    = HOUR_HEIGHT * 24; // 1440px
const TOTAL_MINUTES  = 24 * 60;         // 1440
const SNAP           = 15;              // minute snap for drag-create

// ── State ─────────────────────────────────────────────────────────────────────
let weekStart = getWeekStart(new Date());
let events    = [];   // raw events from server for current week

// ── DOM refs ──────────────────────────────────────────────────────────────────
const weekLabel     = document.getElementById('week-label');
const btnPrev       = document.getElementById('btn-prev');
const btnToday      = document.getElementById('btn-today');
const btnNext       = document.getElementById('btn-next');
const daysWrapper   = document.getElementById('days-wrapper');
const timeGutter    = document.getElementById('time-gutter');
const modalOverlay  = document.getElementById('modal-overlay');
const modalTitle    = document.getElementById('modal-title');
const eventForm     = document.getElementById('event-form');
const fTitle        = document.getElementById('f-title');
const fStart        = document.getElementById('f-start');
const fEnd          = document.getElementById('f-end');
const formError     = document.getElementById('form-error');
const btnSave       = document.getElementById('btn-save');
const btnDelete     = document.getElementById('btn-delete');
const btnCancel     = document.getElementById('btn-cancel');

// ── Navigation ────────────────────────────────────────────────────────────────
btnPrev.addEventListener('click', () => {
  weekStart = addWeeks(weekStart, -1);
  loadWeek();
});
btnToday.addEventListener('click', () => {
  weekStart = getWeekStart(new Date());
  loadWeek();
});
btnNext.addEventListener('click', () => {
  weekStart = addWeeks(weekStart, 1);
  loadWeek();
});

// ── Load & Render ─────────────────────────────────────────────────────────────
async function loadWeek() {
  weekLabel.textContent = formatWeekLabel(weekStart);

  const weekEnd = new Date(weekStart);
  weekEnd.setDate(weekEnd.getDate() + 7);

  try {
    events = await fetchEvents(toLocalIso(weekStart), toLocalIso(weekEnd));
  } catch (err) {
    console.error('Failed to load events:', err);
    events = [];
  }

  renderWeek();
}

function renderWeek() {
  const today    = new Date();
  const weekDays = getWeekDays(weekStart);

  // ── Render time gutter ──────────────────────────────────────────────────
  timeGutter.innerHTML = '';
  for (let h = 0; h <= 24; h++) {
    const div = document.createElement('div');
    div.className = 'gutter-hour';
    div.textContent = h === 24 ? '' : `${String(h).padStart(2, '0')}:00`;
    timeGutter.appendChild(div);
  }

  // ── Build days wrapper content ──────────────────────────────────────────
  daysWrapper.innerHTML = '';

  // Sticky header row
  const headerRow = document.createElement('div');
  headerRow.id = 'days-header-row';

  // Grid of day columns
  const daysGrid = document.createElement('div');
  daysGrid.id = 'days-grid';

  weekDays.forEach((day, dayIndex) => {
    const isToday = isSameDay(day, today);

    // Header cell
    const hdr = document.createElement('div');
    hdr.className = 'day-header' + (isToday ? ' today' : '');
    const { dayName, dayNum } = formatDayHeader(day);
    hdr.innerHTML = `
      <span class="day-name">${dayName}</span>
      <span class="day-date">${dayNum}</span>
    `;
    headerRow.appendChild(hdr);

    // Day column
    const col = document.createElement('div');
    col.className = 'day-col' + (isToday ? ' today' : '');
    col.dataset.dayIndex = dayIndex;

    // Day body (the scrollable time area)
    const body = document.createElement('div');
    body.className = 'day-body';

    // Hour and half-hour lines
    for (let h = 0; h < 24; h++) {
      const hourLine = document.createElement('div');
      hourLine.className = 'hour-line';
      hourLine.style.top = `${h * HOUR_HEIGHT}px`;
      body.appendChild(hourLine);

      const halfLine = document.createElement('div');
      halfLine.className = 'half-line';
      halfLine.style.top = `${h * HOUR_HEIGHT + HOUR_HEIGHT / 2}px`;
      body.appendChild(halfLine);
    }
    // Bottom border line
    const bottomLine = document.createElement('div');
    bottomLine.className = 'hour-line';
    bottomLine.style.top = `${AXIS_HEIGHT}px`;
    body.appendChild(bottomLine);

    // Attach drag-to-create listeners
    attachDragCreate(body, day);

    // Render events for this day
    const dayEvents = events.filter(ev => {
      const evStart = new Date(ev.start_at);
      const evEnd   = new Date(ev.end_at);
      // Event belongs to this day column if its start is on this day
      // (events are rendered in the column of their start date)
      return isSameDay(evStart, day);
    });

    const layoutItems = computeDayLayout(dayEvents);
    layoutItems.forEach(item => {
      const block = createEventBlock(item, body);
      body.appendChild(block);
    });

    col.appendChild(body);
    daysGrid.appendChild(col);
  });

  // Wrap header + grid in a flex column inside daysWrapper
  const inner = document.createElement('div');
  inner.style.cssText = 'display:flex;flex-direction:column;flex:1;min-width:0;';
  inner.appendChild(headerRow);
  inner.appendChild(daysGrid);
  daysWrapper.appendChild(inner);

  // Scroll to 07:00 on initial render
  daysWrapper.scrollTop = 7 * HOUR_HEIGHT;
}

// ── Event Block ───────────────────────────────────────────────────────────────
function createEventBlock(item, container) {
  const { event, colIndex, colCount } = item;

  const startDate = new Date(event.start_at);
  const endDate   = new Date(event.end_at);

  // Clamp to [0, TOTAL_MINUTES]
  const startMin = Math.max(0, Math.min(TOTAL_MINUTES, minutesFromMidnight(startDate)));
  const endMin   = Math.max(0, Math.min(TOTAL_MINUTES, minutesFromMidnight(endDate)));

  const top    = (startMin / TOTAL_MINUTES) * AXIS_HEIGHT;
  const height = Math.max(2, ((endMin - startMin) / TOTAL_MINUTES) * AXIS_HEIGHT);

  // Horizontal layout: use percentage-based positioning
  // We'll compute as percentages of the container width
  const leftPct  = (colIndex / colCount) * 100;
  const widthPct = (1 / colCount) * 100;

  const block = document.createElement('div');
  block.className = 'event-block';
  block.style.top    = `${top}px`;
  block.style.height = `${height}px`;
  block.style.left   = `calc(${leftPct}% + 1px)`;
  block.style.width  = `calc(${widthPct}% - 2px)`;

  const timeStr = `${formatTime(startDate)} – ${formatTime(endDate)}`;
  block.innerHTML = `
    <div class="ev-title">${escapeHtml(event.title)}</div>
    <div class="ev-time">${timeStr}</div>
  `;

  block.addEventListener('click', e => {
    e.stopPropagation();
    openEditModal(event);
  });

  return block;
}

// ── Drag-to-Create ────────────────────────────────────────────────────────────
function attachDragCreate(body, day) {
  let dragStart = null;
  let selectionEl = null;

  function yToMinutes(y) {
    const raw = (y / AXIS_HEIGHT) * TOTAL_MINUTES;
    return Math.max(0, Math.min(TOTAL_MINUTES, snapMinutes(raw, SNAP)));
  }

  function minutesToY(min) {
    return (min / TOTAL_MINUTES) * AXIS_HEIGHT;
  }

  body.addEventListener('mousedown', e => {
    // Only left-click on the body itself (not on event blocks)
    if (e.button !== 0) return;
    if (e.target !== body && !e.target.classList.contains('hour-line') && !e.target.classList.contains('half-line')) return;

    e.preventDefault();
    const rect = body.getBoundingClientRect();
    const y = e.clientY - rect.top + body.closest('#days-wrapper').scrollTop;
    // Adjust for sticky header
    const headerHeight = document.getElementById('days-header-row').offsetHeight;
    const adjustedY = e.clientY - rect.top;

    dragStart = yToMinutes(adjustedY);

    selectionEl = document.createElement('div');
    selectionEl.className = 'drag-selection';
    const snapY = minutesToY(dragStart);
    selectionEl.style.top    = `${snapY}px`;
    selectionEl.style.height = `${HOUR_HEIGHT}px`; // default 1 hour
    body.appendChild(selectionEl);
  });

  document.addEventListener('mousemove', onMouseMove);
  document.addEventListener('mouseup', onMouseUp);

  function onMouseMove(e) {
    if (dragStart === null || !selectionEl) return;
    const rect = body.getBoundingClientRect();
    const adjustedY = e.clientY - rect.top;
    const currentMin = yToMinutes(adjustedY);

    const startMin = Math.min(dragStart, currentMin);
    const endMin   = Math.max(dragStart, currentMin);
    const clampedEnd = endMin === startMin ? startMin + SNAP : endMin;

    selectionEl.style.top    = `${minutesToY(startMin)}px`;
    selectionEl.style.height = `${minutesToY(clampedEnd) - minutesToY(startMin)}px`;
  }

  function onMouseUp(e) {
    if (dragStart === null || !selectionEl) return;

    const rect = body.getBoundingClientRect();
    const adjustedY = e.clientY - rect.top;
    const endMin = yToMinutes(adjustedY);

    let startMin = Math.min(dragStart, endMin);
    let finalEnd = Math.max(dragStart, endMin);
    if (finalEnd === startMin) finalEnd = startMin + SNAP;

    // Clamp
    startMin = Math.max(0, Math.min(TOTAL_MINUTES - SNAP, startMin));
    finalEnd = Math.max(startMin + SNAP, Math.min(TOTAL_MINUTES, finalEnd));

    selectionEl.remove();
    selectionEl = null;
    dragStart = null;

    // Build datetime strings for the selected day
    const startDate = new Date(day);
    startDate.setHours(Math.floor(startMin / 60), startMin % 60, 0, 0);
    const endDate = new Date(day);
    endDate.setHours(Math.floor(finalEnd / 60), finalEnd % 60, 0, 0);

    openCreateModal(startDate, endDate);
  }
}

// ── Modal ─────────────────────────────────────────────────────────────────────
let editingEventId = null;

function showModal() {
  modalOverlay.classList.remove('hidden');
  fTitle.focus();
}

function hideModal() {
  modalOverlay.classList.add('hidden');
  editingEventId = null;
  formError.classList.add('hidden');
  formError.textContent = '';
}

function openCreateModal(startDate, endDate) {
  editingEventId = null;
  modalTitle.textContent = 'New Event';
  fTitle.value = '';
  fStart.value = toInputDatetime(startDate);
  fEnd.value   = toInputDatetime(endDate);
  btnDelete.classList.add('hidden');
  formError.classList.add('hidden');
  showModal();
}

function openEditModal(event) {
  editingEventId = event.id;
  modalTitle.textContent = 'Edit Event';
  fTitle.value = event.title;
  fStart.value = toInputDatetime(new Date(event.start_at));
  fEnd.value   = toInputDatetime(new Date(event.end_at));
  btnDelete.classList.remove('hidden');
  formError.classList.add('hidden');
  showModal();
}

function showFormError(msg) {
  formError.textContent = msg;
  formError.classList.remove('hidden');
}

// Form submit
eventForm.addEventListener('submit', async e => {
  e.preventDefault();
  formError.classList.add('hidden');

  const title    = fTitle.value.trim();
  const startVal = fStart.value;
  const endVal   = fEnd.value;

  if (!title) {
    showFormError('Title is required.');
    return;
  }
  if (!startVal || !endVal) {
    showFormError('Start and end times are required.');
    return;
  }

  const startDate = new Date(startVal);
  const endDate   = new Date(endVal);
  if (endDate <= startDate) {
    showFormError('End time must be after start time.');
    return;
  }

  const payload = {
    title,
    start_at: toLocalIso(startDate),
    end_at:   toLocalIso(endDate),
  };

  btnSave.disabled = true;
  try {
    if (editingEventId !== null) {
      await updateEvent(editingEventId, payload);
    } else {
      await createEvent(payload);
    }
    hideModal();
    await loadWeek();
  } catch (err) {
    showFormError(err.message || 'Failed to save event.');
  } finally {
    btnSave.disabled = false;
  }
});

// Delete button
btnDelete.addEventListener('click', async () => {
  if (editingEventId === null) return;
  if (!confirm('Delete this event?')) return;

  btnDelete.disabled = true;
  try {
    await deleteEvent(editingEventId);
    hideModal();
    await loadWeek();
  } catch (err) {
    showFormError(err.message || 'Failed to delete event.');
  } finally {
    btnDelete.disabled = false;
  }
});

// Cancel button
btnCancel.addEventListener('click', hideModal);

// Click outside modal to close
modalOverlay.addEventListener('click', e => {
  if (e.target === modalOverlay) hideModal();
});

// Escape key
document.addEventListener('keydown', e => {
  if (e.key === 'Escape') hideModal();
});

// ── Utilities ─────────────────────────────────────────────────────────────────
function escapeHtml(str) {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// ── Boot ──────────────────────────────────────────────────────────────────────
loadWeek();
"}

