 * Cluster-based overlap layout engine.
 *
 * Given a list of events for a single day, computes for each event:
 *   - colIndex:    which column within its cluster (0-based)
 *   - colCount:    the number of columns this event must share
 *                  (= the maximum number of simultaneously active columns
 *                   at any point during this event's duration)
 *
 * The caller maps these to pixel geometry:
 *   left  = (colIndex / colCount) * dayColumnWidth
 *   width = dayColumnWidth / colCount
 *
 * ── Algorithm ────────────────────────────────────────────────────────────────
 *
 * Phase 1 – Cluster detection (transitive overlap grouping)
 *   Sort events by start time. Sweep through; maintain the running maximum
 *   end time of the current cluster. When an event starts at or after that
 *   maximum, it belongs to a new cluster.
 *
 * Phase 2 – Column assignment (greedy, within each cluster)
 *   Maintain colEnds[c] = end time of the last event placed in column c.
 *   For each event (sorted by start, then longer-first), find the first
 *   column c where colEnds[c] <= event.start; assign it there and update
 *   colEnds[c] = event.end. If no free column exists, open a new one.
 *
 * Phase 3 – Per-event colCount (contention width)
 *   For each event, colCount = the number of columns that are "active"
 *   (i.e. have an event overlapping this event's time range) at the moment
 *   of maximum contention during this event's duration.
 *   Concretely: for event E, count how many other events in the same cluster
 *   overlap E (start_other < end_E AND end_other > start_E), then add 1 for
 *   E itself. That is the colCount for E.
 *
 *   This ensures:
 *   - An event that overlaps nothing gets colCount = 1 (full width).
 *   - In a chain A–B–C where A overlaps B and B overlaps C but A does not
 *     overlap C: A gets colCount = 2, B gets colCount = 2, C gets colCount = 2
 *     (B is the bottleneck). Each event is still fully visible.
 *   - Three identical-time events each get colCount = 3.
 */

/**
 * @typedef {{ id: number, start_at: string, end_at: string, title: string }} CalEvent
 * @typedef {{ event: CalEvent, colIndex: number, colCount: number }} LayoutItem
 */

/**
 * @param {CalEvent[]} events  All events for one day (any order).
 * @returns {LayoutItem[]}
 */
export function computeDayLayout(events) {
  if (events.length === 0) return [];

  // Convert to working objects with numeric timestamps
  const items = events.map(ev => ({
    event:    ev,
    start:    new Date(ev.start_at).getTime(),
    end:      new Date(ev.end_at).getTime(),
    colIndex: 0,
    colCount: 1,
  }));

  // Sort by start time, then by end time descending (longer events first)
  items.sort((a, b) => a.start - b.start || b.end - a.end);

  // ── Phase 1: Build clusters ───────────────────────────────────────────────
  const clusters = [];
  let currentCluster = [];
  let clusterMaxEnd  = -Infinity;

  for (const item of items) {
    if (currentCluster.length > 0 && item.start >= clusterMaxEnd) {
      clusters.push(currentCluster);
      currentCluster = [];
      clusterMaxEnd  = -Infinity;
    }
    currentCluster.push(item);
    if (item.end > clusterMaxEnd) clusterMaxEnd = item.end;
  }
  if (currentCluster.length > 0) clusters.push(currentCluster);

  // ── Phase 2 & 3: Column assignment + per-event colCount ──────────────────
  for (const cluster of clusters) {
    // ── 2a. Assign column indices greedily ──────────────────────────────
    const colEnds = []; // colEnds[c] = end time of last event in column c

    for (const item of cluster) {
      let placed = false;
      for (let c = 0; c < colEnds.length; c++) {
        if (colEnds[c] <= item.start) {
          item.colIndex = c;
          colEnds[c]    = item.end;
          placed = true;
          break;
        }
      }
      if (!placed) {
        item.colIndex = colEnds.length;
        colEnds.push(item.end);
      }
    }

    // ── 2b. Compute per-event colCount ──────────────────────────────────
    // For each event E, colCount(E) = 1 + number of other events in the
    // cluster that overlap E.
    // Two events overlap iff start_a < end_b AND start_b < end_a.
    for (const item of cluster) {
      let overlapping = 1; // count E itself
      for (const other of cluster) {
        if (other === item) continue;
        if (other.start < item.end && other.end > item.start) {
          overlapping++;
        }
      }
      item.colCount = overlapping;
    }
