{"path": "client/src/style.css", "content": "/* ── Reset & Base ─────────────────────────────────────────────────────────── */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --header-height: 56px;
  --day-header-height: 48px;
  /* Total scrollable height for 24 hours */
  --hour-height: 60px; /* px per hour */
  --axis-height: calc(var(--hour-height) * 24); /* 1440px */
  --gutter-width: 52px;
  --col-gap: 1px;
  --today-bg: #fffbeb;
  --event-radius: 4px;
  --border-color: #e2e8f0;
  --hour-line-color: #e2e8f0;
  --half-line-color: #f1f5f9;
  --text-primary: #1e293b;
  --text-secondary: #64748b;
  --accent: #3b82f6;
  --accent-hover: #2563eb;
  --danger: #ef4444;
  --danger-hover: #dc2626;
  --event-default-bg: #3b82f6;
  --event-default-border: #2563eb;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 14px;
  color: var(--text-primary);
}

html, body {
  height: 100%;
  background: #f8fafc;
}

#app {
  display: flex;
  flex-direction: column;
  height: 100vh;
  overflow: hidden;
}

/* ── Header ───────────────────────────────────────────────────────────────── */
#cal-header {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 16px;
  height: var(--header-height);
  background: #fff;
  border-bottom: 1px solid var(--border-color);
  flex-shrink: 0;
  z-index: 10;
}

.nav-controls {
  display: flex;
  gap: 6px;
}

.nav-controls button {
  padding: 6px 14px;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  background: #fff;
  cursor: pointer;
  font-size: 13px;
  color: var(--text-primary);
  transition: background 0.15s;
}

.nav-controls button:hover {
  background: #f1f5f9;
}

#week-label {
  font-size: 16px;
  font-weight: 600;
  color: var(--text-primary);
}

/* ── Calendar Container ───────────────────────────────────────────────────── */
#cal-container {
  display: flex;
  flex: 1;
  overflow: hidden;
  background: #fff;
}

/* ── Time Gutter ──────────────────────────────────────────────────────────── */
#time-gutter {
  width: var(--gutter-width);
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  /* top padding to align with day headers */
  padding-top: var(--day-header-height);
  overflow: hidden;
  border-right: 1px solid var(--border-color);
  background: #fff;
  z-index: 5;
}

.gutter-hour {
  height: var(--hour-height);
  flex-shrink: 0;
  display: flex;
  align-items: flex-start;
  justify-content: flex-end;
  padding-right: 8px;
  padding-top: 0;
  font-size: 11px;
  color: var(--text-secondary);
  /* Shift label up so it sits on the line */
  transform: translateY(-7px);
  user-select: none;
}

.gutter-hour:first-child {
  /* 00:00 label: don't show it above the grid */
  visibility: hidden;
}

/* ── Days Wrapper ─────────────────────────────────────────────────────────── */
#days-wrapper {
  display: flex;
  flex: 1;
  overflow-y: scroll;
  overflow-x: hidden;
  position: relative;
}

/* Sticky day headers sit inside days-wrapper */
#days-header-row {
  position: sticky;
  top: 0;
  z-index: 6;
  display: flex;
  width: 100%;
  background: #fff;
  border-bottom: 1px solid var(--border-color);
  flex-shrink: 0;
}

/* ── Day Columns ──────────────────────────────────────────────────────────── */
#days-grid {
  display: flex;
  flex: 1;
  width: 100%;
}

.day-col {
  flex: 1;
  min-width: 0;
  border-right: 1px solid var(--border-color);
  position: relative;
  background: #fff;
}

.day-col:last-child {
  border-right: none;
}

.day-col.today {
  background: var(--today-bg);
}

/* Day header inside the sticky row */
.day-header {
  flex: 1;
  min-width: 0;
  height: var(--day-header-height);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border-right: 1px solid var(--border-color);
  user-select: none;
  cursor: default;
}

.day-header:last-child {
  border-right: none;
}

.day-header .day-name {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
}

.day-header .day-date {
  font-size: 20px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.2;
}

.day-header.today .day-date {
  background: var(--accent);
  color: #fff;
  border-radius: 50%;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
}

/* ── Time Grid Lines ──────────────────────────────────────────────────────── */
.day-body {
  position: relative;
  height: var(--axis-height);
  width: 100%;
}

.hour-line {
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--hour-line-color);
  pointer-events: none;
}

.half-line {
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--half-line-color);
  pointer-events: none;
}

/* Drag-selection highlight */
.drag-selection {
  position: absolute;
  left: 2px;
  right: 2px;
  background: rgba(59, 130, 246, 0.15);
  border: 1px dashed var(--accent);
  border-radius: var(--event-radius);
  pointer-events: none;
  z-index: 2;
}

/* ── Event Blocks ─────────────────────────────────────────────────────────── */
.event-block {
  position: absolute;
  border-radius: var(--event-radius);
  background: var(--event-default-bg);
  border-left: 3px solid var(--event-default-border);
  color: #fff;
  padding: 2px 5px;
  overflow: hidden;
  cursor: pointer;
  z-index: 3;
  transition: filter 0.1s;
  /* Prevent text selection during drag */
  user-select: none;
}

.event-block:hover {
  filter: brightness(1.1);
  z-index: 4;
}

.event-block .ev-title {
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.3;
}

.event-block .ev-time {
  font-size: 10px;
  opacity: 0.9;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.3;
}

/* ── Modal ────────────────────────────────────────────────────────────────── */
#modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
}

#modal-overlay.hidden {
  display: none;
}

#modal-box {
  background: #fff;
  border-radius: 10px;
  padding: 24px;
  width: 360px;
  max-width: 95vw;
  box-shadow: 0 20px 60px rgba(0,0,0,0.2);
}

#modal-title {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 16px;
  color: var(--text-primary);
}

#event-form label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
  margin-bottom: 4px;
  margin-top: 12px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

#event-form label:first-of-type {
  margin-top: 0;
}

#event-form input {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  font-size: 14px;
  color: var(--text-primary);
  outline: none;
  transition: border-color 0.15s;
}

#event-form input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(59,130,246,0.15);
