*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --header-height:     56px;
  --day-header-height: 52px;
  --hour-height:       60px;   /* px per hour */
  --axis-height:       calc(var(--hour-height) * 24); /* 1440px */
  --gutter-width:      56px;
  --border-color:      #e2e8f0;
  --hour-line-color:   #e2e8f0;
  --half-line-color:   #f1f5f9;
  --today-bg:          #fffbeb;
  --event-radius:      4px;
  --text-primary:      #1e293b;
  --text-secondary:    #64748b;
  --accent:            #3b82f6;
  --accent-hover:      #2563eb;
  --danger:            #ef4444;
  --danger-hover:      #dc2626;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 14px;
  color: var(--text-primary);
}

html, body {
  height: 100%;
  background: #f8fafc;
  overflow: hidden;
}

#app {
  display: flex;
  flex-direction: column;
  height: 100vh;
  overflow: hidden;
}

/* ── Top Navigation Header ────────────────────────────────────────────────── */
#cal-header {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 16px;
  height: var(--header-height);
  background: #fff;
  border-bottom: 1px solid var(--border-color);
  flex-shrink: 0;
  z-index: 20;
}

.nav-controls {
  display: flex;
  gap: 6px;
}

.nav-controls button {
  padding: 6px 14px;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  background: #fff;
  cursor: pointer;
  font-size: 13px;
