.nav-controls button {
  padding: 6px 14px;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  background: #fff;
  cursor: pointer;
  font-size: 13px;
  color: var(--text-primary);
  transition: background 0.15s;
}

.nav-controls button:hover {
  background: #f1f5f9;
}

#week-label {
  font-size: 16px;
  font-weight: 600;
  color: var(--text-primary);
}

/* ── Day Headers Bar (fixed, not scrollable) ──────────────────────────────── */
#day-headers-bar {
  display: flex;
  flex-shrink: 0;
  background: #fff;
  border-bottom: 1px solid var(--border-color);
  z-index: 10;
}

#gutter-spacer {
  width: var(--gutter-width);
  flex-shrink: 0;
  border-right: 1px solid var(--border-color);
}

#day-headers {
  display: flex;
  flex: 1;
}

.day-header {
  flex: 1;
  min-width: 0;
  height: var(--day-header-height);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border-right: 1px solid var(--border-color);
  user-select: none;
}

.day-header:last-child {
  border-right: none;
}

.day-header .day-name {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  line-height: 1.2;
}

.day-header .day-date {
  font-size: 20px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.2;
  margin-top: 2px;
}

.day-header.today .day-date {
  background: var(--accent);
  color: #fff;
  border-radius: 50%;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  margin-top: 2px;
}

/* ── Scroll Area ──────────────────────────────────────────────────────────── */
#scroll-area {
  display: flex;
  flex: 1;
  overflow-y: scroll;
  overflow-x: hidden;
  background: #fff;
}

/* ── Time Gutter ──────────────────────────────────────────────────────────── */
#time-gutter {
  width: var(--gutter-width);
  flex-shrink: 0;
  position: relative;
  height: var(--axis-height);
  border-right: 1px solid var(--border-color);
  background: #fff;
}

.gutter-label {
  position: absolute;
  right: 8px;
  font-size: 11px;
  color: var(--text-secondary);
  /* Shift label up so it sits on the hour line */
  transform: translateY(-50%);
  user-select: none;
  white-space: nowrap;
}

/* ── Days Grid ────────────────────────────────────────────────────────────── */
#days-grid {
  display: flex;
  flex: 1;
  min-width: 0;
  height: var(--axis-height);
}

/* ── Day Column ───────────────────────────────────────────────────────────── */
.day-col {
  flex: 1;
  min-width: 0;
  position: relative;
  border-right: 1px solid var(--border-color);
  background: #fff;
  height: var(--axis-height);
}

.day-col:last-child {
  border-right: none;
}

.day-col.today {
  background: var(--today-bg);
}

/* ── Hour / Half-hour Lines ───────────────────────────────────────────────── */
.hour-line {
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--hour-line-color);
  pointer-events: none;
  z-index: 1;
}

.half-line {
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--half-line-color);
  pointer-events: none;
  z-index: 1;
}

/* ── Drag Selection Highlight ─────────────────────────────────────────────── */
.drag-selection {
  position: absolute;
  left: 2px;
  right: 2px;
  background: rgba(59, 130, 246, 0.12);
  border: 1.5px dashed var(--accent);
  border-radius: var(--event-radius);
  pointer-events: none;
  z-index: 2;
}

/* ── Event Blocks ─────────────────────────────────────────────────────────── */
.event-block {
  position: absolute;
  border-radius: var(--event-radius);
  background: #3b82f6;
  border-left: 3px solid #1d4ed8;
  color: #fff;
  padding: 3px 5px 2px;
  overflow: hidden;
  cursor: pointer;
  z-index: 3;
  transition: filter 0.1s, box-shadow 0.1s;
  user-select: none;
  /* Ensure text doesn't overflow the block */
  min-height: 18px;
}

.event-block:hover {
  filter: brightness(1.08);
  box-shadow: 0 2px 8px rgba(0,0,0,0.18);
  z-index: 4;
}

.event-block .ev-title {
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.3;
}

.event-block .ev-time {
  font-size: 10px;
  opacity: 0.88;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.3;
}

/* ── Modal ────────────────────────────────────────────────────────────────── */
#modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
}

#modal-overlay.hidden {
  display: none;
}

#modal-box {
  background: #fff;
  border-radius: 10px;
  padding: 24px;
  width: 360px;
  max-width: 95vw;
  box-shadow: 0 20px 60px rgba(0,0,0,0.2);
}

#modal-title {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 16px;
  color: var(--text-primary);
}

#event-form label {
  display: block;
  font-size: 11px;
  font-weight: 700;
  color: var(--text-secondary);
  margin-bottom: 4px;
  margin-top: 14px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

#event-form label:first-of-type {
  margin-top: 0;
}

#event-form input {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  font-size: 14px;
  color: var(--text-primary);
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
  background: #fff;
}

#event-form input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(59,130,246,0.15);
}

.form-error {
  margin-top: 12px;
  padding: 8px 10px;
  background: #fef2f2;
  border: 1px solid #fecaca;
  border-radius: 6px;
  color: var(--danger);
  font-size: 13px;
  line-height: 1.4;
}

.form-error.hidden {
  display: none;
}

.form-actions {
  display: flex;
  gap: 8px;
  margin-top: 20px;
}

.form-actions button {
  padding: 8px 18px;
  border-radius: 6px;
  border: none;
  cursor: pointer;
  font-size: 14px;
  font-weight: 600;
  transition: background 0.15s;
}

#btn-save {
  background: var(--accent);
  color: #fff;
  flex: 1;
}

#btn-save:hover {
  background: var(--accent-hover);
}

#btn-save:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

#btn-delete {
  background: var(--danger);
  color: #fff;
}

#btn-delete:hover {
  background: var(--danger-hover);
}

#btn-delete:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

#btn-cancel {
  background: #f1f5f9;
  color: var(--text-primary);
}

#btn-cancel:hover {
  background: #e2e8f0;
}

button.hidden {
  display: none !important;
}

/* ── Scrollbar ────────────────────────────────────────────────────────────── */
#scroll-area::-webkit-scrollbar {
  width: 8px;
}
#scroll-area::-webkit-scrollbar-track {
  background: #f1f5f9;
}
#scroll-area::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 4px;
}

/* ── Responsive ───────────────────────────────────────────────────────────── */
@media (max-width: 640px) {
  :root {
    --gutter-width: 38px;
    --hour-height:  48px;
  }
  .day-header .day-date {
    font-size: 15px;
  }
  .day-header .day-name {
    font-size: 9px;
  }
  .day-header.today .day-date {
    width: 26px;
    height: 26px;
    font-size: 13px;
  }
}
"}

{"path": "client/src/main.js", "content": "import './style.css';
import { computeDayLayout } from './layout.js';
import { fetchEvents, createEvent, updateEvent, deleteEvent } from './api.js';
import {
  getWeekStart,
  getWeekDays,
  addWeeks,
  toLocalIso,
  toInputDatetime,
  formatTime,
  formatDayHeader,
  formatWeekLabel,
  isSameDay,
  minutesFromMidnight,
  snapMinutes,
} from './dates.js';

// ── Constants ─────────────────────────────────────────────────────────────────
// These must match the CSS custom properties.
const HOUR_HEIGHT   = 60;          // px per hour  (--hour-height)
const AXIS_HEIGHT   = HOUR_HEIGHT * 24; // 1440px total
const TOTAL_MINUTES = 24 * 60;    // 1440
const SNAP          = 15;          // minute snap for drag-create

// ── State ─────────────────────────────────────────────────────────────────────
let weekStart = getWeekStart(new Date());
let events    = [];

// ── DOM refs ──────────────────────────────────────────────────────────────────
const weekLabel    = document.getElementById('week-label');
const btnPrev      = document.getElementById('btn-prev');
const btnToday     = document.getElementById('btn-today');
const btnNext      = document.getElementById('btn-next');
const scrollArea   = document.getElementById('scroll-area');
const timeGutter   = document.getElementById('time-gutter');
const daysGrid     = document.getElementById('days-grid');
const dayHeaders   = document.getElementById('day-headers');
const modalOverlay = document.getElementById('modal-overlay');
const modalTitle   = document.getElementById('modal-title');
const eventForm    = document.getElementById('event-form');
const fTitle       = document.getElementById('f-title');
const fStart       = document.getElementById('f-start');
const fEnd         = document.getElementById('f-end');
const formError    = document.getElementById('form-error');
const btnSave      = document.getElementById('btn-save');
const btnDelete    = document.getElementById('btn-delete');
const btnCancel    = document.getElementById('btn-cancel');

// ── Navigation ────────────────────────────────────────────────────────────────
btnPrev.addEventListener('click', () => {
  weekStart = addWeeks(weekStart, -1);
  loadWeek();
});
btnToday.addEventListener('click', () => {
  weekStart = getWeekStart(new Date());
  loadWeek();
});
btnNext.addEventListener('click', () => {
  weekStart = addWeeks(weekStart, 1);
  loadWeek();
});

// ── Load & Render ─────────────────────────────────────────────────────────────
async function loadWeek() {
  weekLabel.textContent = formatWeekLabel(weekStart);

  const weekEnd = new Date(weekStart);
  weekEnd.setDate(weekEnd.getDate() + 7);

  try {
    events = await fetchEvents(toLocalIso(weekStart), toLocalIso(weekEnd));
  } catch (err) {
    console.error('Failed to load events:', err);
    events = [];
  }

  renderWeek();
}

function renderWeek() {
  const today    = new Date();
  const weekDays = getWeekDays(weekStart);

  // ── Time gutter ─────────────────────────────────────────────────────────
  timeGutter.innerHTML = '';
  // Hour labels at each hour mark (1–23; skip 0 and 24 to avoid clutter)
  for (let h = 1; h < 24; h++) {
    const label = document.createElement('div');
    label.className = 'gutter-label';
    label.style.top = `${h * HOUR_HEIGHT}px`;
    label.textContent = `${String(h).padStart(2, '0')}:00`;
    timeGutter.appendChild(label);
  }

  // ── Day header cells ─────────────────────────────────────────────────────
  dayHeaders.innerHTML = '';
  weekDays.forEach(day => {
    const isToday = isSameDay(day, today);
    const { dayName, dayNum } = formatDayHeader(day);

    const hdr = document.createElement('div');
    hdr.className = 'day-header' + (isToday ? ' today' : '');
    hdr.innerHTML = `
      <span class="day-name">${dayName}</span>
      <span class="day-date">${dayNum}</span>
    `;
    dayHeaders.appendChild(hdr);
  });

  // ── Day columns ──────────────────────────────────────────────────────────
  daysGrid.innerHTML = '';
  weekDays.forEach(day => {
    const isToday = isSameDay(day, today);

    const col = document.createElement('div');
    col.className = 'day-col' + (isToday ? ' today' : '');

    // Hour and half-hour grid lines
    for (let h = 0; h < 24; h++) {
      const hourLine = document.createElement('div');
      hourLine.className = 'hour-line';
      hourLine.style.top = `${h * HOUR_HEIGHT}px`;
      col.appendChild(hourLine);

      const halfLine = document.createElement('div');
      halfLine.className = 'half-line';
      halfLine.style.top = `${h * HOUR_HEIGHT + HOUR_HEIGHT / 2}px`;
      col.appendChild(halfLine);
    }
    // Bottom boundary line
    const bottomLine = document.createElement('div');
    bottomLine.className = 'hour-line';
    bottomLine.style.top = `${AXIS_HEIGHT}px`;
    col.appendChild(bottomLine);

    // Drag-to-create interaction
    attachDragCreate(col, day);

    // Events for this day
    const dayEvents = events.filter(ev => isSameDay(new Date(ev.start_at), day));
    const layoutItems = computeDayLayout(dayEvents);
    layoutItems.forEach(item => {
      col.appendChild(createEventBlock(item));
    });

    daysGrid.appendChild(col);
  });

  // Scroll to 07:00 on initial render (only if at top)
  if (scrollArea.scrollTop === 0) {
    scrollArea.scrollTop = 7 * HOUR_HEIGHT;
  }
}

// ── Event Block ───────────────────────────────────────────────────────────────
function createEventBlock({ event, colIndex, colCount }) {
  const startDate = new Date(event.start_at);
  const endDate   = new Date(event.end_at);

  // Minutes from midnight, clamped to [0, TOTAL_MINUTES]
  const startMin = Math.max(0, Math.min(TOTAL_MINUTES, minutesFromMidnight(startDate)));
  const endMin   = Math.max(0, Math.min(TOTAL_MINUTES, minutesFromMidnight(endDate)));

  // Pixel geometry
  const top    = (startMin / TOTAL_MINUTES) * AXIS_HEIGHT;
  const height = Math.max(4, ((endMin - startMin) / TOTAL_MINUTES) * AXIS_HEIGHT);

  // Horizontal geometry (percentage-based, with 1px inset on each side)
  const leftPct  = (colIndex / colCount) * 100;
  const widthPct = (1 / colCount) * 100;

  const block = document.createElement('div');
  block.className = 'event-block';
  block.style.top    = `${top}px`;
  block.style.height = `${height}px`;
  block.style.left   = `calc(${leftPct}% + 1px)`;
  block.style.width  = `calc(${widthPct}% - 2px)`;

  const timeStr = `${formatTime(startDate)} – ${formatTime(endDate)}`;
  block.innerHTML = `
    <div class="ev-title">${escapeHtml(event.title)}</div>
    <div class="ev-time">${timeStr}</div>
  `;

  block.addEventListener('click', e => {
    e.stopPropagation();
    openEditModal(event);
  });

  return block;
}

// ── Drag-to-Create ────────────────────────────────────────────────────────────
function attachDragCreate(col, day) {
  let dragStartMin = null;
  let selectionEl  = null;

  /**
   * Convert a mouse clientY to minutes-from-midnight within this column,
   * snapped to SNAP-minute intervals.
   */
  function clientYToMinutes(clientY) {
    const rect = col.getBoundingClientRect();
    const y    = clientY - rect.top;
    const raw  = (y / AXIS_HEIGHT) * TOTAL_MINUTES;
    return Math.max(0, Math.min(TOTAL_MINUTES, snapMinutes(raw, SNAP)));
  }

  function minutesToPx(min) {
    return (min / TOTAL_MINUTES) * AXIS_HEIGHT;
  }

  col.addEventListener('mousedown', e => {
    if (e.button !== 0) return;
    // Only trigger on the column background / grid lines, not on event blocks
    if (
      e.target !== col &&
      !e.target.classList.contains('hour-line') &&
      !e.target.classList.contains('half-line')
    ) return;

    e.preventDefault();
    dragStartMin = clientYToMinutes(e.clientY);

    selectionEl = document.createElement('div');
    selectionEl.className = 'drag-selection';
    selectionEl.style.top    = `${minutesToPx(dragStartMin)}px`;
    selectionEl.style.height = `${minutesToPx(dragStartMin + SNAP) - minutesToPx(dragStartMin)}px`;
    col.appendChild(selectionEl);
  });

  // Use document-level listeners so drag works even if mouse leaves the column
  function onMouseMove(e) {
    if (dragStartMin === null || !selectionEl) return;
    const currentMin = clientYToMinutes(e.clientY);
    const startMin   = Math.min(dragStartMin, currentMin);
    const endMin     = Math.max(dragStartMin, currentMin);
    const finalEnd   = endMin === startMin ? startMin + SNAP : endMin;

    selectionEl.style.top    = `${minutesToPx(startMin)}px`;
    selectionEl.style.height = `${minutesToPx(finalEnd) - minutesToPx(startMin)}px`;
  }

  function onMouseUp(e) {
    if (dragStartMin === null || !selectionEl) return;

    const currentMin = clientYToMinutes(e.clientY);
    let startMin = Math.min(dragStartMin, currentMin);
    let endMin   = Math.max(dragStartMin, currentMin);
    if (endMin === startMin) endMin = startMin + SNAP;

    // Clamp to valid range
    startMin = Math.max(0, Math.min(TOTAL_MINUTES - SNAP, startMin));
    endMin   = Math.max(startMin + SNAP, Math.min(TOTAL_MINUTES, endMin));

    selectionEl.remove();
    selectionEl  = null;
    dragStartMin = null;

    // Build Date objects for the selected time range
    const startDate = new Date(day);
    startDate.setHours(Math.floor(startMin / 60), startMin % 60, 0, 0);
    const endDate = new Date(day);
    endDate.setHours(Math.floor(endMin / 60), endMin % 60, 0, 0);

    openCreateModal(startDate, endDate);
  }

  document.addEventListener('mousemove', onMouseMove);
  document.addEventListener('mouseup',   onMouseUp);
}

// ── Modal ─────────────────────────────────────────────────────────────────────
let editingEventId = null;

function showModal() {
  modalOverlay.classList.remove('hidden');
  setTimeout(() => fTitle.focus(), 50);
}

function hideModal() {
  modalOverlay.classList.add('hidden');
  editingEventId = null;
  formError.classList.add('hidden');
  formError.textContent = '';
}

function openCreateModal(startDate, endDate) {
  editingEventId = null;
  modalTitle.textContent = 'New Event';
  fTitle.value = '';
  fStart.value = toInputDatetime(startDate);
  fEnd.value   = toInputDatetime(endDate);
  btnDelete.classList.add('hidden');
  formError.classList.add('hidden');
  showModal();
}

function openEditModal(event) {
  editingEventId = event.id;
  modalTitle.textContent = 'Edit Event';
  fTitle.value = event.title;
  fStart.value = toInputDatetime(new Date(event.start_at));
  fEnd.value   = toInputDatetime(new Date(event.end_at));
  btnDelete.classList.remove('hidden');
  formError.classList.add('hidden');
  showModal();
}

function showFormError(msg) {
  formError.textContent = msg;
  formError.classList.remove('hidden');
}

// ── Form Submission ───────────────────────────────────────────────────────────
eventForm.addEventListener('submit', async e => {
  e.preventDefault();
  formError.classList.add('hidden');

  const title    = fTitle.value.trim();
  const startVal = fStart.value;
  const endVal   = fEnd.value;

  // Client-side validation
  if (!title) {
    showFormError('Title is required.');
    return;
  }
  if (!startVal || !endVal) {
    showFormError('Start and end times are required.');
    return;
  }
  const startDate = new Date(startVal);
  const endDate   = new Date(endVal);
  if (isNaN(startDate.getTime()) || isNaN(endDate.getTime())) {
    showFormError('Invalid date/time values.');
    return;
  }
  if (endDate <= startDate) {
    showFormError('End time must be after start time.');
    return;
  }

  const payload = {
    title,
    start_at: toLocalIso(startDate),
    end_at:   toLocalIso(endDate),
  };

  btnSave.disabled = true;
  try {
    if (editingEventId !== null) {
      await updateEvent(editingEventId, payload);
    } else {
      await createEvent(payload);
    }
    hideModal();
    await loadWeek();
  } catch (err) {
    showFormError(err.message || 'Failed to save event.');
  } finally {
    btnSave.disabled = false;
  }
});

// ── Delete ────────────────────────────────────────────────────────────────────
btnDelete.addEventListener('click', async () => {
  if (editingEventId === null) return;
  if (!confirm('Delete this event?')) return;

  btnDelete.disabled = true;
  try {
    await deleteEvent(editingEventId);
    hideModal();
    await loadWeek();
  } catch (err) {
    showFormError(err.message || 'Failed to delete event.');
  } finally {
    btnDelete.disabled = false;
  }
});

// ── Modal Dismiss ─────────────────────────────────────────────────────────────
btnCancel.addEventListener('click', hideModal);

modalOverlay.addEventListener('click', e => {
  if (e.target === modalOverlay) hideModal();
});

document.addEventListener('keydown', e => {
  if (e.key === 'Escape' && !modalOverlay.classList.contains('hidden')) {
    hideModal();
  }
});

// ── Utilities ─────────────────────────────────────────────────────────────────
function escapeHtml(str) {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// ── Boot ──────────────────────────────────────────────────────────────────────
loadWeek();
"}

